from pathlib import Path

# Set this to your server's documents directory.
DOCUMENTS_DIR = Path("/srv/documents").resolve()


def read_document(filename: str) -> str:
    """Read a UTF-8 document by filename, without allowing directory traversal."""
    if not isinstance(filename, str):
        raise TypeError("filename must be a string")

    if (
        not filename
        or filename in {".", ".."}
        or any(char in filename for char in ("/", "\\", "\x00"))
    ):
        raise ValueError("Provide a filename only, not a path")

    path = (DOCUMENTS_DIR / filename).resolve(strict=True)

    # Also reject symlinks pointing outside the documents directory.
    try:
        path.relative_to(DOCUMENTS_DIR)
    except ValueError:
        raise ValueError("File must be inside the documents directory") from None

    return path.read_text(encoding="utf-8")
```

