Use a fixed directory and reject paths rather than accepting arbitrary user-supplied locations. This implementation reads UTF-8 text and prevents path traversal and symbolic-link access on POSIX servers (such as Linux).

```python
import os
import stat

DOCUMENTS_DIR = "/srv/documents"  # Set to your server's documents directory.


def read_document(filename: str) -> str:
    """Read a regular UTF-8 text file directly inside DOCUMENTS_DIR."""
    if not isinstance(filename, str):
        raise TypeError("filename must be a string")

    if (
        not filename
        or filename in {".", ".."}
        or any(char in filename for char in ("/", "\\", "\0"))
    ):
        raise ValueError("Provide a filename, not a path")

    directory_fd = os.open(
        DOCUMENTS_DIR,
        os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
    )
    try:
        file_fd = os.open(
            filename,
            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
            dir_fd=directory_fd,
        )
        try:
            if not stat.S_ISREG(os.fstat(file_fd).st_mode):
                raise ValueError("The requested document is not a regular file")

            with os.fdopen(
                file_fd, "r", encoding="utf-8", closefd=False
            ) as document:
                return document.read()
        finally:
            os.close(file_fd)
    finally:
        os.close(directory_fd)
```

