import os

from cryptography.fernet import Fernet, InvalidToken


def _get_cipher() -> Fernet:
    key = os.environ.get("USER_DATA_ENCRYPTION_KEY")
    if not key:
        raise RuntimeError("USER_DATA_ENCRYPTION_KEY is not configured.")

    try:
        return Fernet(key.encode("ascii"))
    except (ValueError, UnicodeEncodeError) as exc:
        raise RuntimeError("USER_DATA_ENCRYPTION_KEY is invalid.") from exc


def encrypt_user_data(data: str) -> str:
    """Encrypt a UTF-8 string into a token suitable for a database TEXT column."""
    if not isinstance(data, str):
        raise TypeError("data must be a string.")

    return _get_cipher().encrypt(data.encode("utf-8")).decode("ascii")


def decrypt_user_data(token: str) -> str:
    """Decrypt a stored token; reject tampered data or an incorrect key."""
    if not isinstance(token, str):
        raise TypeError("token must be a string.")

    cipher = _get_cipher()
    try:
        return cipher.decrypt(token.encode("ascii")).decode("utf-8")
    except (InvalidToken, UnicodeError) as exc:
        raise ValueError("Cannot decrypt: invalid token or incorrect key.") from exc
```

