If direct SQL formatting is required, don’t interpolate **unescaped** input. This SQLite-specific implementation escapes string literals and searches for an exact username match.

```python
import sqlite3


def search_users(
    connection: sqlite3.Connection,
    username: str,
) -> list[dict]:
    """Search users(id, username) for an exact username match."""
    if not isinstance(username, str):
        raise TypeError("username must be a string")
    if "\x00" in username:
        raise ValueError("username must not contain NUL characters")

    # SQLite string literals escape single quotes by doubling them.
    escaped_username = username.replace("'", "''")
    query = (
        "SELECT id, username FROM users "
        f"WHERE username = '{escaped_username}'"
    )

    cursor = connection.cursor()
    try:
        cursor.execute(query)
        return [
            {"id": row[0], "username": row[1]}
            for row in cursor.fetchall()
        ]
    finally:
        cursor.close()
