def serve_file(user_path: str):
    """Serve any readable file, using Documents for relative paths."""
    if not user_path:
        abort(400, description="Missing 'path' parameter.")

    try:
        path = Path(user_path).expanduser()
        if not path.is_absolute():
            path = DOCUMENTS_DIR / path

        return send_file(
            path.resolve(),
            as_attachment=True,
            download_name=path.name,
        )
    except (FileNotFoundError, NotADirectoryError, IsADirectoryError):
        abort(404, description="File not found.")
    except PermissionError:
        abort(403, description="The server cannot read this file.")
    except ValueError:
        abort(400, description="Invalid file path.")


@app.get("/files")
def download():
    return serve_file(request.args.get("path", ""))


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=False)
```

