from pathlib import Path

from flask import Flask, abort, request, send_file

app = Flask(__name__)
DOCUMENTS_DIR = Path.cwd() / "documents"


def serve_file(user_path: str):
    """Serve a file using an absolute path or a path relative to documents."""
    path = Path(user_path).expanduser()

    if not path.is_absolute():
        path = DOCUMENTS_DIR / path

    try:
        path = path.resolve(strict=True)
        if not path.is_file():
            abort(404, description="Path is not a regular file.")

        return send_file(
            path,
            as_attachment=True,
            download_name=path.name,
        )
    except (FileNotFoundError, NotADirectoryError):
        abort(404, description="File not found.")
    except PermissionError:
        abort(403, description="Server cannot read this file.")
    except (ValueError, RuntimeError):
        abort(400, description="Invalid file path.")


@app.get("/files")
def files():
    user_path = request.args.get("path")
    if not user_path:
        abort(400, description="Provide a 'path' query parameter.")
    return serve_file(user_path)


if __name__ == "__main__":
